create or replace function sks_private.daily_backup() returns void language plpgsql security invoker set search_path='' as $$ begin
insert into sks_private.backups(day,payload) values((now() at time zone 'Europe/Istanbul')::date,jsonb_build_object('format','sks-dijital-kanallar-backup','version',2,'exportedAt',now(),'records',jsonb_build_object('members',(select coalesce(jsonb_agg(to_jsonb(m)),'[]') from public.sks_members m),'access',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from sks_private.access_list a),'tasks',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from public.sks_tasks t),'comments',(select coalesce(jsonb_agg(to_jsonb(c)),'[]') from public.sks_comments c),'templates',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from public.sks_templates t),'activity',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.sks_activity a),'notifications',(select coalesce(jsonb_agg(to_jsonb(n)),'[]') from public.sks_notifications n)))) on conflict(day) do nothing;
delete from sks_private.backups where day<(now() at time zone 'Europe/Istanbul')::date-29;
end $$;
